/**
 * Local filesystem storage driver.
 *
 * **Writes outside the web root.** The directory sits under `server/.storage`,
 * which is not served by Express or by Vite, so a photo is never reachable by
 * URL — only through the authenticated route that streams it.
 *
 * Keys are generated by the server as UUIDs. The path check below is defence
 * against a future caller passing something else: without it, a key of
 * `../../.env` would write or read outside the storage root. Even though no
 * current code can produce such a key, the check is cheap and the failure mode
 * is severe.
 */

import { mkdir, readFile, rename, unlink, writeFile } from 'node:fs/promises';
import { dirname, join, resolve, sep } from 'node:path';
import type { StorageDriver, StoredObject } from './types.js';

/** Absolute path to the storage root. Not inside `client/` or any served directory. */
const ROOT = resolve(process.env.STORAGE_DIR ?? join(process.cwd(), '.storage'));

/**
 * Resolves a key to an absolute path inside ROOT, or throws.
 *
 * Rejects absolute keys, traversal, and anything that escapes after
 * normalisation — including Windows separators and encoded dots.
 */
function pathFor(key: string): string {
  if (key === '' || key.includes('\0')) throw new Error('Invalid storage key');

  const target = resolve(ROOT, key);

  // `resolve` normalises `..`, so comparing prefixes is the reliable check.
  if (target !== ROOT && !target.startsWith(ROOT + sep)) {
    throw new Error('Invalid storage key');
  }

  return target;
}

export function createLocalDriver(): StorageDriver {
  return {
    // `contentType` is part of the interface for drivers that must record it
    // (Supabase stores it as object metadata). This one always writes WebP, and
    // the reader sets the header, so the value is not needed here.
    async put(key, data) {
      const target = pathFor(key);
      await mkdir(dirname(target), { recursive: true });

      // Write then rename: a crash mid-write must not leave a half image that
      // later looks like a valid one.
      const temporary = `${target}.tmp`;
      await writeFile(temporary, data);
      await rename(temporary, target);
    },

    async get(key): Promise<StoredObject | null> {
      try {
        const data = await readFile(pathFor(key));
        // Everything this driver stores is WebP; the caller sets the header.
        return { data, contentType: 'image/webp' };
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === 'ENOENT') return null;
        throw error;
      }
    },

    async remove(key) {
      try {
        await unlink(pathFor(key));
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === 'ENOENT') return;
        throw error;
      }
    },
  };
}

/** Exposed for tests and for the startup log. */
export const storageRoot = ROOT;
